use pest::Parser;
use pest_derive::Parser;

#[derive(Parser)]
#[grammar = "grammar.pest"]
pub struct JPortalParser;

// The Rule enum is automatically generated by pest_derive and available directly
// We can use it as Rule::database, Rule::identifier, etc.

// Data structures representing the parsed database
#[derive(Debug, Clone)]
pub struct Database {
    pub name: String,
    pub userid: String,
    pub password: String,
    pub flags: Vec<String>,
    pub package_name: Option<String>,
    pub output: Option<String>,
    pub imports: Vec<String>,
    pub server: String,
    pub schema: Option<String>,
    pub tables: Vec<Table>,
    pub views: Vec<View>,
}

#[derive(Debug, Clone)]
pub struct Table {
    pub name: String,
    pub alias: Option<String>,
    pub check: Option<String>,
    pub comments: Vec<String>,
    pub options: Vec<String>,
    pub fields: Vec<Field>,
    pub keys: Vec<Key>,
    pub links: Vec<Link>,
    pub grants: Vec<Grant>,
    pub views: Vec<View>,
    pub consts: Vec<Const>,
    pub procs: Vec<Proc>,
    pub parameters: Vec<Parameter>,
    pub is_import: bool,
    pub import_fields: Vec<String>,
    pub is_literal: bool,
    pub literal_name: String,
    pub start_line: Option<i32>,
    pub has_execute: bool,
    pub has_select: bool,
    pub has_delete: bool,
    pub has_insert: bool,
    pub has_update: bool,
    pub has_primary_key: bool,
    pub has_sequence: bool,
    pub has_sequence_returning: bool,
    pub has_identity: bool,
    pub has_std_procs: bool,
    pub has_big_xml: bool,
    pub has_big_json: bool,
}

impl Table {
    // Helper method to check if table has a field - matches JavaCC hasField()
    pub fn has_field(&self, field_name: &str) -> bool {
        self.fields.iter().any(|f| f.name == field_name)
    }
    
    // Helper method to set primary key on a field - matches JavaCC setPrimary()
    pub fn set_primary(&mut self, field_name: &str) {
        if let Some(field) = self.fields.iter_mut().find(|f| f.name == field_name) {
            field.is_primary = true;
        }
    }
    
    // Helper method to check if table has a procedure - matches JavaCC hasProc()
    pub fn has_proc(&self, proc: &Proc) -> bool {
        self.procs.iter().any(|p| p.name == proc.name)
    }
    
    // Helper method to check if field is nullable - matches JavaCC hasFieldAsNull()
    pub fn has_field_as_null(&self, field_name: &str) -> bool {
        if let Some(field) = self.fields.iter().find(|f| f.name == field_name) {
            field.is_null
        } else {
            true // Default to nullable if field not found
        }
    }
}

#[derive(Debug, Clone)]
pub struct Field {
    pub name: String,
    pub alias: Option<String>,
    pub field_type: FieldType,
    pub length: Option<i32>,
    pub precision: Option<i32>,
    pub scale: Option<i32>,
    pub is_null: bool,
    pub is_calc: bool,
    pub default_value: Option<String>,
    pub check_value: Option<String>,
    pub comments: Vec<String>,
    pub enums: Vec<Enum>,
    pub value_list: Vec<String>,
    pub is_literal: bool,
    pub literal_name: String,
    pub is_package_field: bool,
    pub is_sequence: bool,
    pub enum_type: Option<String>,
    pub lookup_name: Option<String>,
    pub enum_link: Option<String>,
    pub is_primary: bool,
    pub is_out: bool,  // For SPROC output fields
}

